CREATE TABLE public.tours (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, duration text NOT NULL, area text NOT NULL, naivasha boolean NOT NULL DEFAULT false, summary text NOT NULL DEFAULT '', highlights text[] NOT NULL DEFAULT '{}', includes text[] NOT NULL DEFAULT '{}', images text[] NOT NULL DEFAULT '{}', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.tours TO anon, authenticated;
GRANT ALL ON public.tours TO service_role;
ALTER TABLE public.tours ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public tour catalogue" ON public.tours FOR SELECT TO anon, authenticated USING (true);
ALTER TABLE public.booking_requests ADD COLUMN safari_answers jsonb NOT NULL DEFAULT '{}'::jsonb;
NOTIFY pgrst, 'reload schema';