INSERT INTO public.tours (slug,name,duration,area,naivasha,summary,highlights,includes,sort_order) VALUES
('lake-naivasha-boat-safari','Lake Naivasha Boat Safari','Half day · approx. 3 hrs','Lake Naivasha',true,'Cruise Kenya''s beautiful freshwater lake past hippo pods, fish eagles, pelicans and over 400 bird species, with Mount Longonot on the horizon.',ARRAY['Hippo viewing','Fish eagle feeding','Papyrus channels','Birdwatching'],ARRAY['1-hour guided boat ride','Life jackets','Park & boat fees','Bottled water'],0),
('crescent-island-walking-safari','Crescent Island Walking Safari','Half day · approx. 4 hrs','Lake Naivasha',true,'Reach the island by boat and walk freely among giraffes, zebras, wildebeest, waterbuck and gazelles — one of the few places in Kenya to safari on foot.',ARRAY['Walk among giraffes','Boat transfer','Expert naturalist guide'],ARRAY['Boat transfer','Guided walk','Entry fees','Bottled water'],1),
('hell-s-gate-cycling-gorge-hike','Hell''s Gate Cycling & Gorge Hike','Full day','Naivasha',true,'Cycle between towering red cliffs past grazing zebra and buffalo, see Fischer''s Tower, then descend into the dramatic Ol Njorowa Gorge with a local guide.',ARRAY['Bike ride','Ol Njorowa Gorge','Fischer''s Tower','Geothermal spa option'],ARRAY['Bike hire','Park fees','Gorge guide','Packed lunch'],2),
('mount-longonot-crater-hike','Mount Longonot Crater Hike','Full day','Naivasha',true,'Climb the dormant volcano to its crater rim for sweeping views over the Rift Valley and Lake Naivasha. Optional full crater-rim loop for keen hikers.',ARRAY['Crater rim views','Rift Valley panorama','Optional rim loop'],ARRAY['Transport','Park fees','Hiking guide','Packed lunch & water'],3),
('naivasha-day-trip-from-nairobi','Naivasha Day Trip from Nairobi','Full day','Nairobi → Naivasha',true,'Stop at the Great Rift Valley viewpoint, take a boat ride on Lake Naivasha, walk Crescent Island and return to Nairobi in the evening.',ARRAY['Rift Valley viewpoint','Boat ride','Crescent Island walk'],ARRAY['Nairobi pick-up & drop-off','Boat & entry fees','Lunch','Driver-guide'],4),
('naivasha-lake-nakuru-explorer','Naivasha & Lake Nakuru Explorer','2 days / 1 night','Naivasha & Nakuru',true,'Spot rhinos, flamingos and tree-climbing lions in Lake Nakuru National Park, then enjoy a lakeside stay and boat ride on Lake Naivasha.',ARRAY['Rhino sanctuary','Flamingo shores','Lakeside lodge','Baboon Cliff'],ARRAY['Safari vehicle','Park fees','Full-board lodge','Boat ride'],5),
('maasai-mara-via-naivasha','Maasai Mara via Naivasha','4 days / 3 nights','Maasai Mara',false,'Kenya''s greatest reserve — the Big Five, vast plains and the Great Migration (July–October) — with a relaxing Naivasha stopover on the way.',ARRAY['Big Five game drives','Maasai village visit','Naivasha boat ride'],ARRAY['4x4 safari vehicle','Park fees','Full-board camps','Professional guide'],6),
('amboseli-elephant-safari','Amboseli Elephant Safari','3 days / 2 nights','Amboseli',false,'Huge elephant herds against the backdrop of Mount Kilimanjaro, plus lions, cheetahs and swamp birdlife.',ARRAY['Kilimanjaro views','Big tusker elephants','Observation Hill'],ARRAY['4x4 safari vehicle','Park fees','Full-board lodge','Guide'],7),
('diani-beach-holiday','Diani Beach Holiday','5 days / 4 nights','South Coast',false,'Unwind on white sands by the Indian Ocean — snorkelling at Kisite marine park, a dhow sunset cruise and Swahili culture.',ARRAY['Snorkelling & dolphins','Dhow cruise','Beach resort'],ARRAY['Transfers','Beach hotel','Kisite excursion','Breakfast & dinner'],8);
